//! Rust port of TPTBox.core.np_utils.binary_dilation_perimeter (TPTBox/core/np_utils.py), generated by fast-anything.
//! Check it with:  fast-anything verify TPTBox.core.np_utils.binary_dilation_perimeter
//!
//! Works on rows along the last axis packed into u64 bitsets.
//!
//! `_get_perimeter_image` marks a voxel inner when its face-neighbour count equals 2*ndim - j for a
//! j no larger than the number of axes on which it lies at an end (j = 0 excluded in 1D, where the
//! code compares `image == 2`). That reduces to:
//! - 1D: only the two ends can be inner, each when its single neighbour is set;
//! - 2D/3D with an axis of size 1: nothing is inner;
//! - 2D/3D otherwise: inner = every face neighbour inside the image is set.
//!
//! The selem is then stamped (OR, centred, clipped) onto perimeter voxels only, as the Python loop does.

use std::borrow::Cow;

use numpy::ndarray::{ArrayD, IxDyn};
use numpy::{IntoPyArray, PyArrayDyn, PyReadonlyArrayDyn, PyUntypedArrayMethods};
use pyo3::exceptions::{PyIndexError, PyRuntimeError, PyValueError};
use pyo3::prelude::*;

// ------------------------------------------------------------------ bit rows (shared with the erosion port)

/// The bytes of a bool array in C order (0 = False), borrowed when it already is C-contiguous.
fn c_order_bytes<'a>(a: &'a PyReadonlyArrayDyn<'_, bool>) -> Cow<'a, [u8]> {
    if a.is_c_contiguous() {
        if let Ok(s) = a.as_slice() {
            // SAFETY: bool and u8 have the same size and alignment; reading as u8 never sees an invalid value
            return Cow::Borrowed(unsafe { std::slice::from_raw_parts(s.as_ptr() as *const u8, s.len()) });
        }
    }
    // a strided view: walk it row by row (ndarray's dynamic-dimension iterator is slow per element)
    let v = a.as_array();
    let shape = v.shape();
    let strides = v.strides();
    let size: usize = shape.iter().product();
    let mut out = Vec::with_capacity(size);
    if size == 0 {
        return Cow::Owned(out);
    }
    let nd = shape.len();
    let p = v.as_ptr() as *const u8;
    if nd == 0 {
        // SAFETY: a 0-d array holds one element at its data pointer
        out.push(unsafe { *p });
        return Cow::Owned(out);
    }
    let (n, sx) = (shape[nd - 1], strides[nd - 1]);
    let mut idx = vec![0usize; nd - 1];
    loop {
        let base: isize = idx.iter().zip(strides).map(|(&i, &s)| i as isize * s).sum();
        // SAFETY: every index is inside the view, so every offset is inside its buffer
        unsafe {
            if sx == 1 {
                out.extend_from_slice(std::slice::from_raw_parts(p.offset(base), n));
            } else {
                for x in 0..n {
                    out.push(*p.offset(base + x as isize * sx));
                }
            }
        }
        // next row (odometer over the leading axes)
        let mut a = nd - 1;
        loop {
            if a == 0 {
                return Cow::Owned(out);
            }
            a -= 1;
            idx[a] += 1;
            if idx[a] < shape[a] {
                break;
            }
            idx[a] = 0;
        }
    }
}

/// Eight bytes (any non-zero byte = set) packed into the low 8 bits, byte i -> bit i.
#[inline(always)]
fn pack8(chunk: &[u8]) -> u64 {
    let v = u64::from_le_bytes(chunk.try_into().unwrap());
    let set = (((v & 0x7f7f_7f7f_7f7f_7f7f).wrapping_add(0x7f7f_7f7f_7f7f_7f7f) | v) & 0x8080_8080_8080_8080) >> 7;
    set.wrapping_mul(0x0102_0408_1020_4080) >> 56
}

/// `rows` rows of `n` bytes into rows of `w` words; bits past `n` stay 0.
fn pack_rows(bytes: &[u8], rows: usize, n: usize, w: usize) -> Vec<u64> {
    let mut bits = vec![0u64; rows * w];
    for r in 0..rows {
        let src = &bytes[r * n..(r + 1) * n];
        let dst = &mut bits[r * w..(r + 1) * w];
        let mut chunks = src.chunks_exact(8);
        let mut pos = 0usize;
        for c in &mut chunks {
            dst[pos >> 6] |= pack8(c) << (pos & 63);
            pos += 8;
        }
        for &b in chunks.remainder() {
            if b != 0 {
                dst[pos >> 6] |= 1 << (pos & 63);
            }
            pos += 1;
        }
    }
    bits
}

const fn spread_table() -> [u64; 256] {
    let mut t = [0u64; 256];
    let mut i = 0;
    while i < 256 {
        let mut v = 0u64;
        let mut b = 0;
        while b < 8 {
            if (i >> b) & 1 == 1 {
                v |= 1u64 << (8 * b);
            }
            b += 1;
        }
        t[i] = v;
        i += 1;
    }
    t
}
static SPREAD: [u64; 256] = spread_table();

/// Rows of `w` words back into `rows` rows of `n` bytes (0/1).
fn unpack_rows(bits: &[u64], rows: usize, n: usize, w: usize) -> Vec<u8> {
    let mut out = vec![0u8; rows * n];
    for r in 0..rows {
        let src = &bits[r * w..(r + 1) * w];
        let dst = &mut out[r * n..(r + 1) * n];
        let mut chunks = dst.chunks_exact_mut(8);
        let mut pos = 0usize;
        for c in &mut chunks {
            let byte = (src[pos >> 6] >> (pos & 63)) & 0xff;
            c.copy_from_slice(&SPREAD[byte as usize].to_le_bytes());
            pos += 8;
        }
        for b in chunks.into_remainder() {
            *b = ((src[pos >> 6] >> (pos & 63)) & 1) as u8;
            pos += 1;
        }
    }
    out
}

/// Valid bits of the last word of a row of length `n` (n >= 1).
#[inline]
fn last_mask(n: usize) -> u64 {
    let r = n & 63;
    if r == 0 { !0 } else { (1u64 << r) - 1 }
}

/// C-order strides of the leading axes, and a row's index along each of them.
struct Lead {
    shape: Vec<usize>,
    stride: Vec<usize>,
}

impl Lead {
    fn new(shape: &[usize]) -> Self {
        let mut stride = vec![1usize; shape.len()];
        for a in (0..shape.len().saturating_sub(1)).rev() {
            stride[a] = stride[a + 1] * shape[a + 1];
        }
        Lead { shape: shape.to_vec(), stride }
    }

    /// The index of row `r` along each leading axis.
    #[inline]
    fn index(&self, r: usize, idx: &mut [usize]) {
        for a in 0..self.shape.len() {
            idx[a] = (r / self.stride[a]) % self.shape[a];
        }
    }

    /// Linear row offset of `delta`.
    fn linear(&self, delta: &[isize]) -> isize {
        delta.iter().zip(&self.stride).map(|(&d, &s)| d * s as isize).sum()
    }

    /// Row `r` (at `idx`) moved by `delta` (linear offset `lin`), if it stays inside the leading axes.
    #[inline]
    fn moved(&self, r: usize, idx: &[usize], delta: &[isize], lin: isize) -> Option<usize> {
        for a in 0..self.shape.len() {
            let i = idx[a] as isize + delta[a];
            if i < 0 || i >= self.shape[a] as isize {
                return None;
            }
        }
        Some((r as isize + lin) as usize)
    }
}

/// 0/1 bytes as bools without copying.
fn into_bools(v: Vec<u8>) -> Vec<bool> {
    let mut v = std::mem::ManuallyDrop::new(v);
    // SAFETY: every byte is 0 or 1, and bool has the size and alignment of u8
    unsafe { Vec::from_raw_parts(v.as_mut_ptr() as *mut bool, v.len(), v.capacity()) }
}

// ------------------------------------------------------------------ dilation

/// `dst[x] |= src[x - t]` for x in [0, n); bits of `src` outside the row read as 0 (its padding is 0).
#[inline]
fn or_shifted(src: &[u64], t: isize, n: usize, dst: &mut [u64]) {
    let w = src.len();
    if t == 0 {
        for k in 0..w {
            dst[k] |= src[k];
        }
    } else if t > 0 {
        let (ws, bs) = (t as usize / 64, t as usize % 64);
        for k in ws..w {
            let mut v = src[k - ws] << bs;
            if bs > 0 && k > ws {
                v |= src[k - ws - 1] >> (64 - bs);
            }
            dst[k] |= v;
        }
    } else {
        let u = (-t) as usize;
        let (ws, bs) = (u / 64, u % 64);
        for k in 0..w {
            let j = k + ws;
            if j >= w {
                break;
            }
            let mut v = src[j] >> bs;
            if bs > 0 && j + 1 < w {
                v |= src[j + 1] << (64 - bs);
            }
            dst[k] |= v;
        }
    }
    dst[w - 1] &= last_mask(n);
}

/// The Python's perimeter image, as bit rows.
fn perimeter(bits: &[u64], shape: &[usize], lead: &Lead, rows: usize, n: usize, w: usize) -> Vec<u64> {
    let mut p = bits.to_vec();
    if shape.len() == 1 {
        // inner[0] / inner[-1] when the single neighbour is set (`image == 2` never matches)
        if n >= 2 {
            let get = |x: usize| (bits[x >> 6] >> (x & 63)) & 1 == 1;
            let (first, last) = (get(1), get(n - 2));
            if first {
                p[0] &= !1;
            }
            if last {
                p[(n - 1) >> 6] &= !(1u64 << ((n - 1) & 63));
            }
        }
        return p;
    }
    if shape.iter().any(|&s| s == 1) {
        return p;
    }
    let nl = shape.len() - 1;
    let mask = last_mask(n);
    let mut deltas: Vec<Vec<isize>> = Vec::with_capacity(2 * nl);
    for a in 0..nl {
        for d in [-1isize, 1] {
            let mut v = vec![0isize; nl];
            v[a] = d;
            deltas.push(v);
        }
    }
    let lins: Vec<isize> = deltas.iter().map(|d| lead.linear(d)).collect();
    let mut nb: Vec<Option<usize>> = vec![None; deltas.len()];
    let mut idx = vec![0usize; nl];
    for r in 0..rows {
        let row = &bits[r * w..(r + 1) * w];
        if row.iter().all(|&x| x == 0) {
            continue;
        }
        lead.index(r, &mut idx);
        for (i, d) in deltas.iter().enumerate() {
            nb[i] = lead.moved(r, &idx, d, lins[i]);
        }
        for k in 0..w {
            let c = row[k];
            if c == 0 {
                continue;
            }
            // x neighbours, outside the row counts as set
            let mut inner = (c >> 1) | if k + 1 < w { row[k + 1] << 63 } else { 1u64 << ((n - 1) & 63) };
            inner &= (c << 1) | if k > 0 { row[k - 1] >> 63 } else { 1 };
            for o in nb.iter().flatten() {
                inner &= bits[o * w + k];
            }
            p[r * w + k] = c & !inner;
        }
        p[r * w + w - 1] &= mask;
    }
    p
}

fn dilate(img: &[u8], shape: &[usize], sel: &[u8], sshape: &[usize]) -> Vec<u8> {
    let nd = shape.len();
    let n = shape[nd - 1];
    let lead = Lead::new(&shape[..nd - 1]);
    let rows: usize = shape[..nd - 1].iter().product();
    let w = n.div_ceil(64);
    let bits = pack_rows(img, rows, n, w);
    let perim = perimeter(&bits, shape, &lead, rows, n, w);

    // selem offsets from its centre, grouped by their leading-axes part
    let mut groups: Vec<(Vec<isize>, Vec<isize>)> = Vec::new();
    let sl = Lead::new(sshape);
    for (i, &v) in sel.iter().enumerate() {
        if v == 0 {
            continue;
        }
        let off: Vec<isize> =
            (0..nd).map(|a| ((i / sl.stride[a]) % sshape[a]) as isize - (sshape[a] / 2) as isize).collect();
        let (ld, ex) = (off[..nd - 1].to_vec(), off[nd - 1]);
        match groups.iter_mut().find(|g| g.0 == ld) {
            Some(g) => g.1.push(ex),
            None => groups.push((ld, vec![ex])),
        }
    }

    let lins: Vec<isize> = groups.iter().map(|g| lead.linear(&g.0)).collect();
    let mut idx = vec![0usize; nd - 1];
    let mut out = bits.clone();
    for r in 0..rows {
        let prow = &perim[r * w..(r + 1) * w];
        if prow.iter().all(|&x| x == 0) {
            continue;
        }
        lead.index(r, &mut idx);
        for ((ld, exs), &lin) in groups.iter().zip(&lins) {
            let Some(t) = lead.moved(r, &idx, ld, lin) else { continue };
            let dst = &mut out[t * w..(t + 1) * w];
            for &ex in exs {
                or_shifted(prow, ex, n, dst);
            }
        }
    }
    unpack_rows(&out, rows, n, w)
}

#[pyfunction]
fn binary_dilation_perimeter<'py>(
    py: Python<'py>,
    image: PyReadonlyArrayDyn<'py, bool>,
    selem: PyReadonlyArrayDyn<'py, bool>,
) -> PyResult<Py<PyArrayDyn<bool>>> {
    let dim = image.ndim();
    if !(1..=3).contains(&dim) {
        return Err(PyRuntimeError::new_err("Only 1D, 2D and 3D images are supported."));
    }
    if selem.ndim() != dim {
        return Err(PyValueError::new_err(format!(
            "structure element must have {dim} dimensions, got {}",
            selem.ndim()
        )));
    }
    let sshape = selem.shape().to_vec();
    if sshape.iter().any(|s| s % 2 == 0) {
        return Err(PyValueError::new_err("Only structure element of odd dimension in each direction is supported."));
    }
    let shape = image.shape().to_vec();
    // _get_perimeter_image indexes position 0 of every axis
    if let Some(ax) = shape.iter().position(|&s| s == 0) {
        return Err(PyIndexError::new_err(format!("index 0 is out of bounds for axis {ax} with size 0")));
    }
    let img = c_order_bytes(&image);
    let sel = c_order_bytes(&selem);
    let out = py.detach(|| dilate(&img, &shape, &sel, &sshape));
    Ok(ArrayD::from_shape_vec(IxDyn(&shape), into_bools(out)).unwrap().into_pyarray(py).unbind())
}

#[pymodule]
fn fa_tptbox_core_np_utils_binary_dilation_perimeter(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(binary_dilation_perimeter, m)?)?;
    Ok(())
}
